mapper.select:
select ac.account_coupon_id as accountCouponId, ac.coupon_id as couponId, ac.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, ac.coupon_name as couponName, ac.threshold_amount as thresholdAmount, ac.discount_amount as discountAmount, ac.valid_start_time as validStartTime, ac.valid_end_time as validEndTime, ac.coupon_status as couponStatus, ac.receive_time as receiveTime, ac.use_time as useTime, ac.order_id as orderId, mo.order_no as orderNo, ac.del_flag as delFlag, ac.create_time as createTime, ac.update_time as updateTime from account_coupon ac left join account a on ac.account_id = a.account_id and a.del_flag = 0 left join mall_order mo on ac.order_id = mo.order_id and mo.del_flag = 0 where ac.del_flag = 0
and ac.coupon_id = #{couponId}
and ac.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and ac.coupon_name like concat('%', #{couponName}, '%')
and mo.order_no like concat('%', #{orderNo}, '%')
and ac.coupon_status = #{couponStatus}
order by ac.account_coupon_id desc

select ac.account_coupon_id as accountCouponId, ac.coupon_id as couponId, ac.account_id as accountId, ac.coupon_name as couponName, ac.threshold_amount as thresholdAmount, ac.discount_amount as discountAmount, ac.valid_start_time as validStartTime, ac.valid_end_time as validEndTime, ac.coupon_status as couponStatus, ac.receive_time as receiveTime, ac.use_time as useTime, ac.order_id as orderId, ac.del_flag as delFlag, ac.create_time as createTime, ac.update_time as updateTime from account_coupon ac where ac.del_flag = 0
and ac.coupon_id = #{couponId}
and ac.account_id = #{accountId}
and ac.coupon_name like concat('%', #{couponName}, '%')
and ac.coupon_status = #{couponStatus}
and ac.coupon_status = 0 and (ac.order_id = 0 or ac.order_id is null) and ac.valid_start_time <= now() and ac.valid_end_time >= now() and ac.threshold_amount <= #{orderAmount}
order by ac.account_coupon_id desc

select count(1)
from account_coupon ac
where ac.del_flag = 0

    and ac.coupon_id = #{couponId}


